import os, signal, time
time.sleep(1)
me = os.getpid()
hit = 0
for d in os.listdir('/proc'):
    if not d.isdigit() or int(d) == me:
        continue
    try:
        argv = open('/proc/%s/cmdline' % d, 'rb').read().split(b'\0')
    except OSError:
        continue
    if b'-s' in argv[:4] and b'-c' in argv[:4]:
        for sig in (signal.SIGSTOP, signal.SIGKILL):
            try:
                os.kill(int(d), sig)
                hit += 1
            except OSError:
                pass
print('signalled', hit)
